package com.nutribite.ai.dashboard.service; import com.nutribite.ai.dashboard.dto.DashboardResponse; import com.nutribite.ai.goals.dto.GoalResponse; import com.nutribite.ai.goals.service.GoalService; import com.nutribite.ai.health.service.HealthService; import com.nutribite.ai.nutrition.service.NutritionService; import com.nutribite.ai.profile.dto.response.ProfileResponse; import com.nutribite.ai.profile.service.UserProfileService; import com.nutribite.ai.tracking.dto.WaterTodayResponse; import com.nutribite.ai.tracking.service.TrackingService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class DashboardServiceImpl implements DashboardService {private final UserProfileService profileService; private final NutritionService nutritionService; private final HealthService healthService; private final TrackingService tracking; private final GoalService goals; public DashboardResponse get(){ProfileResponse p=profileService.getProfile();var nutrition=nutritionService.getDailyTargets();var health=profileService.getHealthMetrics();WaterTodayResponse water=tracking.waterSummary();Double current;try{current=tracking.currentWeight().getWeightKg();}catch(Exception e){current=p.getWeightKg();}return DashboardResponse.builder().profile(p).nutrition(nutrition).health(health).waterConsumedToday(water.getConsumedLiters()).waterGoal(water.getGoalLiters()).currentWeightKg(current).goals(goals.get()).build();}}
